action_input.code:
import sqlite3
import csv
heroes = {}
with open('csv/superhero.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        hero_id = int(row['id'])
        heroes[hero_id] = row['height_cm']
conn = sqlite3.connect('db/hero_power.db')
cursor = conn.cursor()
cursor.execute('SELECT DISTINCT hero_id FROM hero_power WHERE power_id = 18')
super_strength_ids = [r[0] for r in cursor.fetchall()]
conn.close()
count = 0
for hid in super_strength_ids:
    h = heroes.get(hid, '')
    if h:
        try:
            if float(h) > 200:
                count += 1
        except ValueError:
            pass
print(count)

